                  "related", new SimpleEntityRef( "custom",  entities.get(1).getUuid() ) );
        em.createConnection( new SimpleEntityRef( "custom",  entities.get(1).getUuid() ),
                  "related", new SimpleEntityRef( "custom",  entities.get(0).getUuid() ) );

