                put("user_name", username );
                put("email", email);
                put("rev_sig","dfe5d0d3");
                put("exp", exp);
                put("iat", System.currentTimeMillis());
                put("iss", "https://jwt.example.com/token");
                put("zid","uaa");
                put("aud"," size = 6");
            }};
    }
