        edgeShardSerialization.removeShardMeta( scope, shard3, sourceEdgeMeta ).execute();

        results = edgeShardSerialization.getShardMetaData( scope, Optional.<Shard>absent(), sourceEdgeMeta );


        assertFalse( results.hasNext() );
    }
