        assertFalse( edges.hasNext() );

        serialization.removeEdgeTypeFromSource( scope, edge3 ).execute();

        //check we have nothing
        edges = serialization.getEdgeTypesFromSource( scope, createSearchEdge( sourceId, null ) );

        assertFalse( edges.hasNext() );
    }
