        assertFalse( edges.hasNext() );

        serialization.removeEdgeTypeToTarget( scope, edge3 ).execute();

        //check we have nothing
        edges = serialization.getEdgeTypesToTarget( scope, createSearchEdge( targetId, null ) );

        assertFalse( edges.hasNext() );
    }
