        try {
            compaction.compact( this.scope, directedEdgeMeta, group );
            fail( "I should not reach this point" );
        }
        catch ( Throwable t ) {
            assertEquals( "Correct error message returned", "Compaction cannot be run yet.  Ignoring compaction.",
                t.getMessage() );
        }
    }
